func findSubarrays(nums []int) bool {
	for i := 0; i < len(nums)-1; i++ {
		a := nums[i] + nums[i+1]
		for j := i + 1; j < len(nums)-1; j++ {
			b := nums[j] + nums[j+1]
			if a == b {
				return true
			}
		}
	}
	return false
}

class Solution(object):
    def findSubarrays(self, nums):
        """
        :type nums: List[int]
        :rtype: bool
        """
        s = set([])
        for i in range(len(nums) - 1):
            t = nums[i] + nums[i + 1]
            if t in s:
                return True
            s.add(t)
        return False
